export default JSON.parse("{\"workId\":\"liezi\",\"chapter\":{\"id\":\"liezi_ch-2\",\"workId\":\"liezi\",\"order\":2,\"title\":\"黃帝\",\"difficulty\":2,\"estimatedMinutes\":53,\"passageIds\":[\"liezi_ch-2_p-1\",\"liezi_ch-2_p-2\",\"liezi_ch-2_p-3\",\"liezi_ch-2_p-4\",\"liezi_ch-2_p-5\",\"liezi_ch-2_p-6\",\"liezi_ch-2_p-7\",\"liezi_ch-2_p-8\",\"liezi_ch-2_p-9\",\"liezi_ch-2_p-10\",\"liezi_ch-2_p-11\",\"liezi_ch-2_p-12\",\"liezi_ch-2_p-13\",\"liezi_ch-2_p-14\",\"liezi_ch-2_p-15\",\"liezi_ch-2_p-16\",\"liezi_ch-2_p-17\",\"liezi_ch-2_p-18\",\"liezi_ch-2_p-19\",\"liezi_ch-2_p-20\",\"liezi_ch-2_p-21\"],\"tags\":[]},\"passages\":[{\"id\":\"liezi_ch-2_p-1\",\"chapterId\":\"liezi_ch-2\",\"order\":1,\"canonicalText\":\"黃帝即位十五年，喜天下戴己，養正命，娛耳目，供鼻口，焦然肌色皯黤，昏然五情爽惑。又十五年，憂天下不治，竭聰明，勞智力，焦然肌色皯黤，昏然五情爽惑。黃帝乃慨然歎曰：「朕之過淫矣。養一己其患如此，治萬物其患如此。」乃退而退居大庭之館，齋心服形，三月不親政事。晝寢而夢，遊於華胥氏之國。華胥氏之國在弇州之西，台州之北，不知斯齊國幾千萬裏；蓋非舟車足力之所及，神遊而已。其國無師長，自然而已。其民無嗜慾，自然而已。不知樂生，不知惡死，故無夭殤；不知親己，不知疏物，故無愛憎；不知背逆，不知向順，故無利害：都無所愛惜，都無所畏忌。入水不溺，入火不熱。斫撻無傷痛，指擿無痡癢。乘空如履實，寢虛若處寐。雲霧不硋其視，雷霆不亂其聽，美惡不滑其心，山谷不躓其步，神行而已。黃帝既寤，怡然自得，召天老、力牧、太山稽，告之曰：「朕閑居三月，齋心服形，思所以養身治物之道，弗獲其術。憊而寢，乃夢見華胥氏之國。今朕知夫至道不可以情求矣。朕知之矣！朕得之矣！而不能以告若矣。」又二十八年，天下大治，幾若華胥氏之國，而帝登假。百姓號慟，二百餘年不輟。\",\"sentenceIds\":[\"liezi_ch-2_p-1_s-1\",\"liezi_ch-2_p-1_s-2\",\"liezi_ch-2_p-1_s-3\",\"liezi_ch-2_p-1_s-4\",\"liezi_ch-2_p-1_s-5\",\"liezi_ch-2_p-1_s-6\",\"liezi_ch-2_p-1_s-7\",\"liezi_ch-2_p-1_s-8\",\"liezi_ch-2_p-1_s-9\",\"liezi_ch-2_p-1_s-10\",\"liezi_ch-2_p-1_s-11\",\"liezi_ch-2_p-1_s-12\",\"liezi_ch-2_p-1_s-13\",\"liezi_ch-2_p-1_s-14\",\"liezi_ch-2_p-1_s-15\",\"liezi_ch-2_p-1_s-16\",\"liezi_ch-2_p-1_s-17\",\"liezi_ch-2_p-1_s-18\",\"liezi_ch-2_p-1_s-19\",\"liezi_ch-2_p-1_s-20\",\"liezi_ch-2_p-1_s-21\",\"liezi_ch-2_p-1_s-22\",\"liezi_ch-2_p-1_s-23\",\"liezi_ch-2_p-1_s-24\",\"liezi_ch-2_p-1_s-25\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"黃帝即位治理天下十五年之際，心中欣喜全天下人都愛戴擁護自己，於是竭力養護自己的性命，縱情娛樂自己的耳目視聽，極盡享受口鼻美味香氣，結果身體肌膚反而變得焦枯焦黑（皯黤），精神昏聵五官感知迷亂失常。隨後又過了十五年，他轉而極度憂慮天下治理不好，於是竭盡自己的耳聰目明，耗盡自己的心機智謀日夜操勞，結果身體肌膚依然變得焦枯憔悴，精神五感同樣陷入昏亂迷惘。黃帝於是慨然長嘆道：我的過失實在太過偏激極端了！單純放縱欲望保養個人自身其禍患竟然如此嚴重，單憑主觀智謀強行幹預治理天下萬物其禍患竟然也如此嚴重！於是毅然退隱居處於大庭之館，清心滌慮修養心性、約束形體欲望，整整三個月不親自過問行政政務。一天白天假寐安寢時做了一個夢，夢中自己的精神神遊到了華胥氏之國。華胥氏之國位於弇州的西面、台州的北面，不知道距離中原齊國有幾千萬裏之遙；那絕非舟船車馬與凡人腳力所能抵達的仙境，完全是純粹的精神自由神遊罷了。那個國度沒有發號施令的君主官長，一切完全順應自然而然；那裡的百姓沒有任何非分嗜好貪欲，一切完全順應純樸天性。他們不知道貪生怕死，所以沒有早夭夭亡的悲劇；不知道自私偏愛自己，不知道冷漠排斥外物，所以心中沒有愛恨情仇的撕裂；不知道違背抗拒，不知道刻意逢迎順從，所以世間沒有利害衝突的爭奪；對一切事物都沒有私心貪戀愛惜，對一切變故都沒有恐懼畏忌。跳入水中不會被淹溺，走入烈火不會被灼燒；刀砍鞭抽感受不到傷痛，指掐針刺感受不到痠痛發癢；在虛空中漫步就如同行走在堅實平地上，在虛空中安歇就如同在牀上安睡；濃厚的雲霧無法遮蔽障礙他們的雙眼視線，狂暴的雷霆無法震亂幹擾他們的雙耳聽覺，外在美醜妍媸無法惑亂他們的純淨心靈，險峻的山崩峽谷無法絆倒他們的從容步伐，完全是出神入化的神妙運行罷了！黃帝醒來之後，心中怡然自得通達徹悟，立刻召集天老、力牧、太山稽等輔政大臣，告訴他們說：我退隱靜居三個月，洗滌心靈約束形骸，苦思冥想養生與治國的終極大道，卻始終未能找到具體技術法門。疲憊入睡之後，纔在夢中神遊見到了華胥氏之國。如今我終於深刻懂得：至高的大道是絕不可能依靠主觀人為情緒與私心機巧去強行求索的！我終於理解大道了！我終於領悟真諦了！但我卻無法用死板語言直接傳授告訴你們啊！自此之後又過了二十八年，天下實現了空前清明治平，幾乎達到了如同華胥氏之國那樣無為而治的黃金盛世，隨後黃帝得道昇仙仙逝（帝登假）。全天下百姓悲痛號哭哀悼，長達二百多年未曾停歇！\",\"analysis\":\"【篇旨與黃帝夢遊華胥氏之國道家烏托邦理想國】先秦道家最具浪漫色彩與哲學深度的烏托邦寓言——黃帝由縱欲（養一己）到極端勞心（治萬物）兩度碰壁，最終通過「齋心服形」夢遊華胥之國領悟「無嗜慾、無愛憎、無利害」的無為自化至道，開創天下大治。\\\\n【詞義訓詁】「皯黤」：皯，音感；黤，音掩；肌膚焦枯黑黃病態；「爽惑」：爽，差錯失常；感官功能紊亂；「華胥氏之國」：道家超越物質與階級壓迫的至善理想國；「帝登假」：假通遐，遠去，指帝王仙逝昇天。\\\\n【社會哲學批判】深刻揭示統治者無論個人放縱還是過度行政折騰皆會引發災難，唯有超越功利執念、尊重社會自發秩序，方能實現真正的天下大治。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-2_p-2\",\"chapterId\":\"liezi_ch-2\",\"order\":2,\"canonicalText\":\"列子師老商氏，友伯高子，進二子之道，乘風而歸。尹生聞之，從列子居，數月不處房。間請其術者十度，列子拒之。尹生懟而請辭。列子亦無言。尹生去數月，意不已，復往從之。列子曰：「汝何去來之亟也？」尹生曰：「曩者向先生請其術，先生不告，故懟而去。今已自省，故復來耳。」列子曰：「曩吾以為子達，今子之鄙至此乎！始吾事老商先生，友伯高子，三年之後，心不敢念是非，口不敢言利害，始得老商一眄而已。五年之後，心更念是非，口更言利害，老商始一解顏而笑。七年之後，從心之所念，更無是非；從口之所言，更無利害。夫子始一引吾並席而坐。九年之後，橫心之所念，橫口之所言，亦不知我之是非利害歟，亦不知彼之是非利害歟，外內進矣。而後眼如耳，耳如鼻，鼻如口，口無不同。心凝形釋，骨肉都融；不覺形之所倚，足之所履，心之所念，言之所藏。如斯而已。乘風而行，不知風乘我邪，我乘風邪？今子居先生之門，曾未浹辰，而懟憾者再，子奚得其術哉？」尹生大慚，行不敢出言。\",\"sentenceIds\":[\"liezi_ch-2_p-2_s-1\",\"liezi_ch-2_p-2_s-2\",\"liezi_ch-2_p-2_s-3\",\"liezi_ch-2_p-2_s-4\",\"liezi_ch-2_p-2_s-5\",\"liezi_ch-2_p-2_s-6\",\"liezi_ch-2_p-2_s-7\",\"liezi_ch-2_p-2_s-8\",\"liezi_ch-2_p-2_s-9\",\"liezi_ch-2_p-2_s-10\",\"liezi_ch-2_p-2_s-11\",\"liezi_ch-2_p-2_s-12\",\"liezi_ch-2_p-2_s-13\",\"liezi_ch-2_p-2_s-14\",\"liezi_ch-2_p-2_s-15\",\"liezi_ch-2_p-2_s-16\",\"liezi_ch-2_p-2_s-17\",\"liezi_ch-2_p-2_s-18\",\"liezi_ch-2_p-2_s-19\",\"liezi_ch-2_p-2_s-20\",\"liezi_ch-2_p-2_s-21\",\"liezi_ch-2_p-2_s-22\",\"liezi_ch-2_p-2_s-23\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"列子拜老商氏為師，與伯高子結為摯友，全面學通融會了兩位大師的至高大道，能夠凌空御風而行歸來。鄭國青年尹生聽聞後，前來投奔列子門下求學，連續幾個月不敢回房安歇伺候左右。期間向列子請求傳授御風之術多達十次，列子都堅決拒絕了他。尹生心中怨恨惱怒於是請求辭行離去，列子也平靜無言沒有輓留。尹生離開了幾個月後，內心始終無法放下求道之心，於是又硬著頭皮重新前來跟隨列子。列子問：你為什麼來去如此頻繁匆忙呢？尹生說：過去我向先生請教玄妙之術，先生不肯傳授，所以我心懷怨恨而離去；如今我已深刻自我反省，所以又重新回來了。列子說：過去我還以為你頗有通達資質，如今看來你的鄙陋竟然到了這種地步！當初我事奉老商老師、結交伯高師友之際：三年之中，內心不敢動一絲是非雜念，口中不敢言一句利害得失，才僅僅換來老商老師對我正眼看了一眼（一眄）；五年之後，內心放開思考是非，口中放開探討利害，老商老師才第一次對我展顏微笑；七年之後，任憑內心隨意思索，再也沒有世俗狹隘的是非分別；任憑口中隨意言說，再也沒有世俗功利的利害計較，老師這才第一次拉著我同席並肩而坐！九年之後，任憑內心自由思緒奔湧，任憑口中隨心所欲暢所欲言，我已經完全不知道究竟什麼是我的是非利害，也不知道什麼是別人的是非利害，內在心靈與外在萬物徹底融通無間了！自此之後，我的眼睛如同耳朵一樣能聽，耳朵如同鼻子一樣能聞，鼻子如同嘴巴一樣能嘗，口鼻眼耳所有感官徹底打通毫無分別！心神凝聚專一而形體徹底解脫放下，骨骼肉體完全融化於天地造化之中；絲毫感覺不到身軀所倚靠的支撐，感覺不到雙腳所踩踏的土地，感覺不到內心所思考的意念，感覺不到言語所包藏的機巧。達到這種無拘無束的境界罷了！此時我便能御風而行，完全分不清究竟是長風在駕馭著我飛行，還是我在乘駕著長風飛行了！如今你來到我門下求學，前後連十二天（浹辰）都還沒待滿，卻已經兩次心生怨恨憤懣，你又怎麼可能領悟掌握這通天徹地的至道呢！尹生聽後面紅耳赤無比慚愧，退下後長久不敢再多說一句狂妄之言。\",\"analysis\":\"【篇旨與列子御風九年三階心路修養論】先秦心性哲學與通玄修養最經典之紀錄——列子自述學道九年歷程（三年不敢念是非 → 五年放開心念 → 七年是非泯滅 → 九年內外融通感官互通心凝形釋），揭示御風而行乃心靈徹底擺脫執唸的自然產物。\\\\n【詞義訓詁】「一眄」：眄，音免，斜視、正眼相看；「浹辰」：古代以十二地支記日，十二天為一浹辰；「心凝形釋」：心神凝定、肉身執念徹底消解融化；「眼如耳耳如鼻」：打通感官局限之通感與超驗直覺。\\\\n【學習與心性啟示】痛批急功近利的速成心態，確立任何高階智慧的獲取都必須經歷漫長的心性沉澱、去私去執與本體淬煉。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-2_p-3\",\"chapterId\":\"liezi_ch-2\",\"order\":3,\"canonicalText\":\"列子之齊，中道而反，遇伯昏瞀人。伯昏瞀人曰：「奚方而反？」列子曰：「吾驚焉。」曰：「惡乎驚？」曰：「吾嘗食於十漿，而五漿先饋。」伯昏瞀人曰：「若是，則汝何為驚？」曰：「夫內誠不解，形諜成光，感逮惝恍，使人敬己，而身乃病。夫漿人特賣漿者耳，所引無幾，利勢甚微，猶若是；況萬乘之主，身勞於國而智盡於事，彼將委我以事而效我以功。吾是以驚。」伯昏瞀人曰：「善哉，子之知也！處己如此，物莫能累汝矣。」\",\"sentenceIds\":[\"liezi_ch-2_p-3_s-1\",\"liezi_ch-2_p-3_s-2\",\"liezi_ch-2_p-3_s-3\",\"liezi_ch-2_p-3_s-4\",\"liezi_ch-2_p-3_s-5\",\"liezi_ch-2_p-3_s-6\",\"liezi_ch-2_p-3_s-7\",\"liezi_ch-2_p-3_s-8\",\"liezi_ch-2_p-3_s-9\",\"liezi_ch-2_p-3_s-10\",\"liezi_ch-2_p-3_s-11\",\"liezi_ch-2_p-3_s-12\",\"liezi_ch-2_p-3_s-13\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"列子動身前往齊國，剛走到半路上就突然掉頭返回了，途中偶遇了伯昏瞀人。伯昏瞀人問道：你因為什麼原因半途折返回來了呢？列子說：我在路上遇到一件怪事，感到無比驚恐害怕。伯昏瞀人問：因為什麼事害怕呢？列子說：我在沿途十家賣米漿水飯的小攤上喫漿水，結果竟然有五家攤主爭先恐後地先把熱漿端給我喫（五漿先饋）。伯昏瞀人說：如果是這樣，那你又有什麼好害怕驚恐的呢？列子說：那是因為我內在的得道修為尚未徹底圓融化解無形，鋒芒與光彩外溢顯露於形體神態之上，散發出一種令人恍惚肅然起敬的氣場，致使普通人都對我格外恭敬逢迎，這恰恰說明我的修身已經出現了嚴重的病態漏洞啊！那賣米漿的小販只不過是個做微薄買賣的市井小民罷了，獲取的利潤極其微薄，社會勢力微不足道，尚且對我如此特殊逢迎；更何況那統治萬乘大國的君王呢！大國君王為國家政務身心勞累、智謀耗竭於紛繁事務，一旦看中我的名望，必定會把繁重危險的國政託付於我，強求我建立不世功勳。我正是因此感到無比驚恐害怕而折返回來的啊！伯昏瞀人讚嘆道：太好了，你的見識真是深邃通達啊！你能像這樣清醒防範自律，世間任何物慾名利就再也沒有力量能牽累拖垮你了！\",\"analysis\":\"【篇旨與五漿先饋光芒外露之戒慎微防患】通過列子因「五漿先饋」半途折返的深邃反思，闡明道家「挫其銳、解其紛、和其光、同其塵」的深藏若虛修養，警惕鋒芒外露招致政治重負。\\\\n【詞義訓詁】「五漿先饋」：賣漿者爭先服侍；「形諜成光」：諜通喋，內在修養未純導致神光外露、氣場逼人；「萬乘之主委事效功」：洞悉被最高統治者綁架入政治漩渦的巨大風險。\\\\n【低調自保智慧】真正的成熟是將卓越才華深藏於質樸平淡之中，防範被盛名與公眾期待所綁架。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-2_p-4\",\"chapterId\":\"liezi_ch-2\",\"order\":4,\"canonicalText\":\"伯昏瞀人往見列子，見其門外之屨滿矣。伯昏瞀人北面而立，立柱而杖，柱頤移時，不言而出。擯者以告列子。列子提屨徒跣而走，出及門，曰：「先生既來，曾不發藥乎？」伯昏瞀人曰：「已矣！吾語汝曰：『人將歸汝。』果人歸汝。豈汝能使人歸汝，汝不能使人無歸汝也。奚獨有異於人哉？夫動而不能無使人知，是亦自異於人矣。自異於人，乃所以致患也。」\",\"sentenceIds\":[\"liezi_ch-2_p-4_s-1\",\"liezi_ch-2_p-4_s-2\",\"liezi_ch-2_p-4_s-3\",\"liezi_ch-2_p-4_s-4\",\"liezi_ch-2_p-4_s-5\",\"liezi_ch-2_p-4_s-6\",\"liezi_ch-2_p-4_s-7\",\"liezi_ch-2_p-4_s-8\",\"liezi_ch-2_p-4_s-9\",\"liezi_ch-2_p-4_s-10\",\"liezi_ch-2_p-4_s-11\",\"liezi_ch-2_p-4_s-12\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"伯昏瞀人前往拜訪探望列子，看見列子家門外前來求教求見之人的鞋子堆得滿滿當當（屨滿）。伯昏瞀人面向北面靜靜佇立，把柺杖倚靠在下巴底下，長久沉思良久，一句話也沒說就轉身離開了。負責通報接待的門童把這件事稟告給了列子。列子一聽急忙手提著鞋子連鞋都顧不上穿光著腳狂奔追了出來（徒跣而走），追到大門口喊道：先生既然已經親臨寒舍，難道連一句如良藥般的教誨都不肯賜予我嗎？伯昏瞀人回頭說：算了吧！我過去就告誡過你說：你若鋒芒外露，天下人將紛至沓來歸附於你。如今果然全天下人都奔著你來了！這難道是你故意要讓眾人前來歸附你嗎？這是因為你的修養尚未達到極致，無法做到讓眾人不來追逐包圍你啊！你這樣難道還能自誇與世俗凡人有什麼不同嗎？你的一舉一動無法做到自然無形不為人知，這本身就說明你在標榜自我特異於常人；而自命不凡特異於常人，正是引來滔天禍患的根本源頭啊！\",\"analysis\":\"【篇旨與門外屨滿自異於人名望招禍論】以伯昏瞀人見列子門外「屨滿」拂袖而去為警示，深入剖析盛名之下其實難副的「名人效應危機」，確立不標新立異、歸於平凡的最高防身哲學。\\\\n【詞義訓詁】「屨滿」：屨，音句，鞋子；形容門庭若市、訪客極多；「徒跣」：跣，音顯，赤腳奔跑；「發藥」：以苦口良言作治病良藥；「自異於人」：自我標榜與眾不同。\\\\n【名望管理】過度暴露於聚光燈下必將招致公眾的嚴苛審視與無盡索取，唯有甘於平凡方能守護心靈寧靜。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-2_p-5\",\"chapterId\":\"liezi_ch-2\",\"order\":5,\"canonicalText\":\"列子居鄭之圃，四十餘年，人無知者。國君卿大夫視之，猶眾庶也。子列子游於泰山，見榮啟期行乎郕之野，鹿裘帶索，鼓琴而歌。孔子問曰：「先生何樂也？」對曰：「吾樂甚多：天生萬物，唯人為貴，而吾得為人，是一樂也；男女之別，男尊女卑，故以男為貴，吾得為男矣，是二樂也；人生有不見日月、不免襁褓者，吾既已行年九十矣，是三樂也。貧者士之常也，死者人之終也，處常得終，當何憂哉？」孔子曰：「善哉！能自寬者也。」\",\"sentenceIds\":[\"liezi_ch-2_p-5_s-1\",\"liezi_ch-2_p-5_s-2\",\"liezi_ch-2_p-5_s-3\",\"liezi_ch-2_p-5_s-4\",\"liezi_ch-2_p-5_s-5\",\"liezi_ch-2_p-5_s-6\",\"liezi_ch-2_p-5_s-7\",\"liezi_ch-2_p-5_s-8\",\"liezi_ch-2_p-5_s-9\",\"liezi_ch-2_p-5_s-10\",\"liezi_ch-2_p-5_s-11\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"列子隱居在鄭國圃田長達四十多年，世間沒有誰知道他的深邃道行。鄭國國君與卿大夫看待他如同普通平民百姓一樣。列子在泰山腳下游歷，看見高士榮啟期漫步在郕地的原野上，身上穿著鹿皮粗裘，腰間用繩索當作腰帶隨意綑綁，一邊彈著古琴一邊放聲高歌。孔子（一說列子）走上前問道：先生究竟為什麼如此快樂呢？榮啟期回答說：我的快樂實在太多太多了：天地化育萬物，唯有人類最具靈性最為尊貴，而我有幸降生為人，這是我的第一大快樂；在古代社會性別分工中，我有幸獲得了男子的自主地位，這是我的第二大快樂；人生在世，有許多嬰孩連日月光芒都未曾親眼見過、甚至未能脫離襁褓就不幸夭折，而我如今已經健康活到了九十歲高齡，這是我的第三大快樂！物質貧寒本來就是讀書士人的家常便飯，死亡本來就是所有人類生命的必然終點；安守人生的本常，平靜迎來生命的終局，我還有什麼好憂愁焦慮的呢？孔子讚嘆道：太好了！這真是一位善於自我寬解、心靈無比強大豁達的至者啊！\",\"analysis\":\"【篇旨與榮啟期三樂自寬自得生命境界】記錄春秋高士榮啟期「得為人、得為男、享長壽」之三樂典故，展現超越物質貧困、感恩生命存在的豁達心境。\\\\n【詞義訓詁】「鹿裘帶索」：生活極度簡樸質樸；「行年九十」：壽考康寧；「處常得終」：安於貧寒本常、平靜接納生命終局；「自寬者」：強大的心理調適與認知重塑能力。\\\\n【現代心理學解讀】榮啟期展示了極高水平的「感恩認知重塑法」，在艱苦條件下主動聚焦生命中的積極稟賦，獲取內心恆久的幸福感。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-2_p-6\",\"chapterId\":\"liezi_ch-2\",\"order\":6,\"canonicalText\":\"關尹喜曰：「在己無居，形物其著。其動若水，其靜若鏡，其應若響。故其道若物者也。物自違道，道不違物。善若道者，亦不用耳，亦不用目，亦不用力，亦不用心。欲若道而用視聽形智以求之，弗當矣。瞻之在前，忽焉在後；用之彌滿六虛，廢之莫知其所。亦非有心者所能得遠，亦非無心者所能得近。唯默而得之，而性成之者得之。知而亡情，能而不為，真知真能也。」\",\"sentenceIds\":[\"liezi_ch-2_p-6_s-1\",\"liezi_ch-2_p-6_s-2\",\"liezi_ch-2_p-6_s-3\",\"liezi_ch-2_p-6_s-4\",\"liezi_ch-2_p-6_s-5\",\"liezi_ch-2_p-6_s-6\",\"liezi_ch-2_p-6_s-7\",\"liezi_ch-2_p-6_s-8\",\"liezi_ch-2_p-6_s-9\",\"liezi_ch-2_p-6_s-10\",\"liezi_ch-2_p-6_s-11\",\"liezi_ch-2_p-6_s-12\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"關尹子（尹喜）說：在自己內心深處毫無執念與固執的成見（在己無居），外界萬事萬物的客觀形態自然會清晰映照呈現。行動時如同流水一樣順勢而動隨方就圓，安靜時如同明鏡一樣毫無遮蔽平靜映照，回應事物時如同空谷回聲一樣精準響應。所以遵循大道的人完全順應客觀萬物的自然本性。往往是萬物自己違背了大道，而大道從未主動違背排斥過任何萬物。真正善於體悟順應大道的人，不需要刻意依賴耳朵去探聽，不需要刻意依賴眼睛去窺視，不需要刻意依賴肌肉力量去強求，也不需要刻意依賴機謀心思去算計。企圖契合大道卻偏要用耳目視聽、形體力量與世俗聰明去強行求索，那就完全背道而馳了！看它看似就在眼前，忽然之間又變幻在身後；運用它時浩瀚充塞於宇宙六合虛空之中，收斂不用時卻杳然無蹤不知其所寄。這大道既非懷揣功利有心之人所能強行企及，亦非麻木無知無心之輩所能偶然接近。唯有在靜默無言中深刻領悟、並將其化為本然天性實踐的人才能真正獲得大道。洞曉一切真理卻不放縱私情偏見，具備一切才能卻不肆意妄為造作，這才是真正的大知大能啊！\",\"analysis\":\"【題解與背景】\\\\n本段選自《列子》〈黃帝〉第 21 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「關尹喜曰在己無居形物其著其動若水其靜若鏡……」之章法語感與對偶語氣。\\\\n2. 訓詁與古漢語範式：本段重點解讀「關」、「尹」、「喜」等字詞之古代漢語語意、通假字與名物制度考釋。\\\\n【思想與史事脈絡】\\\\n深刻傳達《列子》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：liezi_ch-2_p-6）。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-2_p-7\",\"chapterId\":\"liezi_ch-2\",\"order\":7,\"canonicalText\":\"列子問於關尹曰：「至人潛行不窒，蹈火不熱，行乎萬物之上而不慄。請問何以至於此？」關尹曰：「是純氣之守也，非智巧果敢之列。居！予語汝。凡有貌象聲色者，皆物也，物與物何以相遠？夫物何足以至此？物相去何遠？夫生於無形而消於無窮，夫形體何足以制物？彼得其情而通其條者，物安得而礙之？彼將處其不淫之度，藏其無端之紀，遊乎萬物之所終始。壹其性，養其氣，含其德，以通乎物之所造。夫若是者，其天守全，其神無隙，物安得而入焉！夫醉者之墜車，雖疾不死。骨節與人同而犯害與人異，其神全也。乘亦不知也，墜亦不知也，死生驚懼不出於其胸中，是故遻物而不慴。彼得全於酒而猶若是，而況得全於天乎？聖人藏於天，故莫之能傷也。」\",\"sentenceIds\":[\"liezi_ch-2_p-7_s-1\",\"liezi_ch-2_p-7_s-2\",\"liezi_ch-2_p-7_s-3\",\"liezi_ch-2_p-7_s-4\",\"liezi_ch-2_p-7_s-5\",\"liezi_ch-2_p-7_s-6\",\"liezi_ch-2_p-7_s-7\",\"liezi_ch-2_p-7_s-8\",\"liezi_ch-2_p-7_s-9\",\"liezi_ch-2_p-7_s-10\",\"liezi_ch-2_p-7_s-11\",\"liezi_ch-2_p-7_s-12\",\"liezi_ch-2_p-7_s-13\",\"liezi_ch-2_p-7_s-14\",\"liezi_ch-2_p-7_s-15\",\"liezi_ch-2_p-7_s-16\",\"liezi_ch-2_p-7_s-17\",\"liezi_ch-2_p-7_s-18\",\"liezi_ch-2_p-7_s-19\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"列子向關尹子請教道：得道的至人潛入深水之中不會窒息，踏入熊熊烈火之中不會感到灼熱，行走在萬丈懸崖虛空之上而內心毫無恐懼顫抖。請問究竟是依靠什麼法門達到這種境界的呢？關尹子說：這是因為他始終守護著純粹無雜的天賦真氣（純氣之守），絕非世俗世間的機巧算計與匹夫盲動的果敢勇武所能企及的！坐下吧！我詳細告訴你。世間凡是具備形貌、物象、聲音、色彩的，全都屬於物質範疇；物質與物質之間本質上又有什麼巨大隔閡呢？物質又怎麼可能真正阻礙禁錮至人呢？物質之間的差距又能有多遠呢？萬物皆誕生於無形大道而最終消散於無窮造化之中，有限的形體物質又怎麼可能制約掌握大道的精神呢？至人領悟了大道的真情而融會貫通了萬物運化的條理脈絡，世間物質又怎麼可能阻礙得了他呢！他居處於永不過度的自然法度之中，將自身鋒芒隱藏在循環無端的宇宙規律裡，自由遨遊於萬物生死終始的造化之中。專一凝斂他的本性，精純葆養他的元氣，深沉蘊含他的崇高德性，以此全面融通萬物被造化生成的源頭。像這樣的人，他天賦的純真元氣完滿無損，他的精神靈性圓融無瑕毫無漏洞，外在的物質傷害又怎麼可能侵入他的身心呢！你看那喝醉酒的人從飛馳的馬車上跌落下來，雖然摔得很重卻往往不會致死。他的骨骼關節與常人完全一樣，但遭受意外傷害的後果卻與常人截然不同，這就是因為他在醉態中精神完全放鬆凝聚一體的緣故啊！乘車時他不知道緊張，跌落時他也沒有恐懼預期，生死驚駭恐懼完全沒有在他胸中產生，所以迎面撞擊外物時內心毫無驚恐痙攣。他在醇酒的麻醉中尚且能夠暫時保全精神免受重傷，又何況是在天地自然大道中完全保全純粹精神的聖人呢！聖人將自己的精神深深寄託隱藏於天地大道之中，所以天下沒有任何物質力量能夠傷害於他啊！\",\"analysis\":\"【篇旨與純氣之守醉者墜車神全不傷形神哲學】先秦形神論巔峯之作——以「醉者墜車疾而不死」為驚人心理生理學比喻，論證精神專一放鬆（神全）能大幅降低物理傷害與應激反應，確立「純氣之守、藏於天莫能傷」的至人境界。\\\\n【詞義訓詁】「純氣之守」：葆養純一無雜之元氣與澄明心境；「遻物而不慴」：遻通遌，相遇碰撞；慴，音涉，恐懼痙攣；「藏於天」：順應自然法則、融於大道。\\\\n【現代身心醫學】人在極度恐懼時肌肉緊繃會加劇外傷與心血管崩潰，而深度心理放鬆與專注（心流狀態）能極大增強生命韌性與應變能力。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-2_p-8\",\"chapterId\":\"liezi_ch-2\",\"order\":8,\"canonicalText\":\"呂梁懸水三十仞，流沫三十里，黿鼉魚鱉之所不能遊也。見一丈夫遊之，以為有苦而欲死也，使弟子並流而拯之。數百步而出，被髮行歌而遊於塘下。孔子從而問焉，曰：「吾以子為鬼，察子則人也。請問：蹈水有道乎？」曰：「亡，吾無道。吾始乎故，長乎性，成乎命。與齊俱入，與汨淈偕出，從水之道而不為私焉。此吾所以蹈水也。」孔子曰：「何謂始乎故，長乎性，成乎命？」曰：「吾生於陵而安於陵，故也；長於水而安於水，性也；不知吾所以然而然，命也。」\",\"sentenceIds\":[\"liezi_ch-2_p-8_s-1\",\"liezi_ch-2_p-8_s-2\",\"liezi_ch-2_p-8_s-3\",\"liezi_ch-2_p-8_s-4\",\"liezi_ch-2_p-8_s-5\",\"liezi_ch-2_p-8_s-6\",\"liezi_ch-2_p-8_s-7\",\"liezi_ch-2_p-8_s-8\",\"liezi_ch-2_p-8_s-9\",\"liezi_ch-2_p-8_s-10\",\"liezi_ch-2_p-8_s-11\",\"liezi_ch-2_p-8_s-12\",\"liezi_ch-2_p-8_s-13\",\"liezi_ch-2_p-8_s-14\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"呂梁瀑布高達三十仞之高，激盪飛濺的浪花泡沫綿延三十里之遠，那是連黿鼉蛟龍魚鱉等水族神物都無法自由游弋的兇險絕境。孔子看見一個男子正在那驚濤駭浪中游水，以為他是遭遇了巨大痛苦想投水自盡，急忙派遣弟子們順著水流奔跑前往救援他。沒想到那男子在激流中游了幾百步便從容登上了岸，披散著頭髮一邊放聲歌唱一邊悠閒地漫步在堤岸之下。孔子快步跟上去請教他，說：我剛才還以為你是神鬼，仔細觀察你才發現是個大活人。請問：您在如此兇險的巨浪中游水，難道有什麼神妙的特殊法術門道嗎？那男子回答說：沒有啊，我並沒有什麼特殊的法術。我一開始順應於自幼養成的習慣（始乎故），在成長中發展了適應水流的天性（長乎性），最終自然成就為不可動搖的命運本能（成乎命）。我跟隨水流旋渦向下旋轉而一同潛入水底（與齊俱入），我跟隨湧起的波濤向上翻滾而一同浮出水面（與汨淈偕出），完全順應水流運行的客觀規律而絕不摻雜絲毫主觀對抗的私心。這就是我能夠在驚濤駭浪中自如游水的全部奧祕了。孔子追問道：什麼叫做始於習慣、長於天性、成於命運呢？男子回答說：我出生在山陵陸地就習慣適應山陵生活，這就是起初的習慣（故）；自幼在水邊長大就自然適應掌握水性，這就是後天發展的天性（性）；完全不需要刻意去思索探究自己為什麼能做到、卻自然而然就能做到，這就是化為本能的命運造化啊（命）！\",\"analysis\":\"【篇旨與呂梁游水始故長性成命順水之道】先秦技能哲學經典名篇——呂梁丈夫在兇險瀑布中「從水之道而不為私、與齊俱入與汨偕出」，深刻揭示徹底順應客觀規律、消除主觀對抗的至高實踐智慧。\\\\n【詞義訓詁】「齊」：齊通臍，水流旋渦核心；「汨淈」：汨，音骨，水流湧起翻騰貌；「不知吾所以然而然」：達到完全自動化、肌肉記憶與本能合一之化境。\\\\n【技能習得理論】從初學規則（故）到適應掌握（性），再到化為無意識本能（命），完美契合現代認知心理學「無意識熟練（Mastery）」之最高境界。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-2_p-9\",\"chapterId\":\"liezi_ch-2\",\"order\":9,\"canonicalText\":\"仲尼適楚，出於林中，見佝僂者承蜩，猶掇之也。仲尼曰：「子巧乎！有道邪？」曰：「我有道也。五六月，累丸二而不墜，則失者鎰少；累三而不墜，則失者十一；累五而不墜，猶掇之也。吾處身也，若橛株駒；吾執臂也，若槁木之枝。雖天地之大，萬物之多，而唯蜩翼之知。吾不反不側，不以萬物易蜩之翼，何為而不得！」孔子顧謂弟子曰：「用志不分，乃凝於神，其佝僂丈人之謂乎！」\",\"sentenceIds\":[\"liezi_ch-2_p-9_s-1\",\"liezi_ch-2_p-9_s-2\",\"liezi_ch-2_p-9_s-3\",\"liezi_ch-2_p-9_s-4\",\"liezi_ch-2_p-9_s-5\",\"liezi_ch-2_p-9_s-6\",\"liezi_ch-2_p-9_s-7\",\"liezi_ch-2_p-9_s-8\",\"liezi_ch-2_p-9_s-9\",\"liezi_ch-2_p-9_s-10\",\"liezi_ch-2_p-9_s-11\",\"liezi_ch-2_p-9_s-12\",\"liezi_ch-2_p-9_s-13\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"孔子前往楚國，途經一片樹林之中，看見一個駝背的老人在用竹竿黏取樹上的蟬（佝僂承蜩），其動作之嫻熟輕鬆，就如同從地上隨手撿拾東西一樣輕而易舉（猶掇之也）。孔子讚嘆道：老先生的技藝真是精巧絕倫啊！這其中難道有什麼特殊門道嗎？駝背老人回答說：我當然有我的門道啊。五六個月練習下來，我在竿頭疊放兩顆泥丸揮動而不掉落，那麼黏蟬失手的概率就很小了；如果在竿頭疊放三顆泥丸而不掉落，那麼失手的概率就只有十分之一了；如果在竿頭疊放五顆泥丸揮動依然紋絲不動不掉落，那麼黏取樹蟬就會像隨手拾物一樣百發百中！我站立自身形體，就如同枯立在地的樹樁殘木一樣巍然不動；我揮動手臂竹竿，就如同枯槁的樹枝一樣自然穩定。雖然天地如此廣大浩瀚，世間萬物如此紛繁多樣，但在我的整個精神世界裡，唯獨只專注認知知曉蟬的那對透明翅膀！我的心神絕不翻覆動搖，絕不因為天地萬物的任何誘惑去置換分散我對蟬翼的極致專注，在這種狀態下又怎麼可能抓不到蟬呢！孔子回頭對弟子們感慨讚嘆道：運用志向意志極致專注而不分散，精神意志才能凝聚達到出神入化的神妙境界，這說的正是這位駝背老丈啊！\",\"analysis\":\"【篇旨與佝僂承蜩用志不分乃凝於神專注心流哲學】古代心理學與工匠精神至高範本——駝背老人以竿頭累丸、身如枯木、心無旁騖黏蟬，孔子總結為「用志不分，乃凝於神」，揭示極致專注成就非凡技藝的普遍法則。\\\\n【詞義訓詁】「佝僂」：駝背老人；「承蜩」：蜩，音條，蟬；用竿頭黏膠黏蟬；「猶掇之」：掇，音多，拾取，比喻極易獲取；「累丸」：在竿頭疊放泥丸練習平衡穩定力。\\\\n【現代心流理論（Flow）】完全沉浸於當下目標、排除一切外界幹擾，達到主客體融為一體的高度專注狀態，是創造頂級技藝與卓越成果的必經之路。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-2_p-10\",\"chapterId\":\"liezi_ch-2\",\"order\":10,\"canonicalText\":\"海上之人有好漚鳥者，每旦之海上，從漚鳥遊，漚鳥之至者百住而不止。其父曰：「吾聞漚鳥皆從汝遊，汝取來，吾玩之。」明日之海上，漚鳥舞而不下也。故曰：至言去言，至為無為。齊智之所知，則淺矣。\",\"sentenceIds\":[\"liezi_ch-2_p-10_s-1\",\"liezi_ch-2_p-10_s-2\",\"liezi_ch-2_p-10_s-3\",\"liezi_ch-2_p-10_s-4\",\"liezi_ch-2_p-10_s-5\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"海邊有一個特別喜愛海鷗海鳥的人，每天清晨都獨自漫步到大海之濱，親密地跟隨海鷗羣一同遊玩嬉戲，飛聚前來環繞落在他身邊的海鷗多達上百隻而盤旋不散。他的父親對他說：我聽說海鷗每天都親近跟隨你一同遊玩，你明天抓一隻活海鷗帶回家來，讓我拿來玩賞玩賞。第二天這個人再次來到海邊，海鷗羣只是在天空高處盤旋飛舞，卻再也沒有一隻願意降落到他的身邊了。所以古人說：至高無上的言語超越了凡俗言語的表達，至高無上的作為順應於無心無為的自然。單憑凡俗世間機巧心機去衡量認識萬物，那認識水平就實在太過淺薄了！\",\"analysis\":\"【篇旨與海翁鷗鳥機心一動鷗鳥不下天人感應心理學】中國哲學史上最著名的「機心（心機謀算）」寓言——海翁無心無欲則百鳥親近，機心一動企圖抓鳥玩賞則海鷗驚覺盤旋不下，揭示動機純潔與信任構建的微妙心理機制。\\\\n【詞義訓詁】「漚鳥」：漚，音歐，海鷗；「百住而不止」：海鷗成百降落停駐；「至言去言，至為無為」：最高溝通超越言語算計，最高作為出於無私純真。\\\\n【信任與博弈論】人與人、人與自然的信任建立在無私坦蕩的真誠基礎之上；一旦動了算計利用的「機心」，微妙的氣場與微表情立刻會破壞信任平衡。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-2_p-11\",\"chapterId\":\"liezi_ch-2\",\"order\":11,\"canonicalText\":\"趙襄子率徒十萬，狩於中山，藉芿燔林，扇烈火，焮百里。有一人從石壁中出，隨煙燼上下，眾謂鬼物。火過，徐行而出，若無所經涉者。襄子怪而留之，徐而察之，形色七竅，人也；氣息音聲，人也。問曰：「子奚道而處石？奚道而入火？」其人曰：「奚物而謂石？奚物而謂火？」襄子曰：「子所出者，石也；子所涉者，火也。」其人曰：「不知也。」魏文侯聞之，問子夏曰：「彼何人哉？」子夏曰：「以商所聞夫子之言，和者大同於物，物無得而傷閡焉，遊金石，蹈水火，皆可也。」文侯曰：「吾子奚不為之？」子夏曰：「刳心去智，商未之能。雖然，試語之：商猶能知之。」文侯曰：「夫子奚不為之？」子夏曰：「夫子能為之，能不為之。」文侯大悅。\",\"sentenceIds\":[\"liezi_ch-2_p-11_s-1\",\"liezi_ch-2_p-11_s-2\",\"liezi_ch-2_p-11_s-3\",\"liezi_ch-2_p-11_s-4\",\"liezi_ch-2_p-11_s-5\",\"liezi_ch-2_p-11_s-6\",\"liezi_ch-2_p-11_s-7\",\"liezi_ch-2_p-11_s-8\",\"liezi_ch-2_p-11_s-9\",\"liezi_ch-2_p-11_s-10\",\"liezi_ch-2_p-11_s-11\",\"liezi_ch-2_p-11_s-12\",\"liezi_ch-2_p-11_s-13\",\"liezi_ch-2_p-11_s-14\",\"liezi_ch-2_p-11_s-15\",\"liezi_ch-2_p-11_s-16\",\"liezi_ch-2_p-11_s-17\",\"liezi_ch-2_p-11_s-18\",\"liezi_ch-2_p-11_s-19\",\"liezi_ch-2_p-11_s-20\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"趙襄子率領十萬大軍隨從，在中山國的崇山密林中舉行大規模圍獵，踐踏枯草、放火焚燒整個森林，狂風煽動滔天烈火，大火焚燒蔓延了一百多里。突然看見有一個人從堅硬的石壁裂縫中緩步走了出來，隨著滾滾濃煙與灰燼上下飄動，眾人都驚呼他是鬼神怪物。大火熄滅過去之後，那人緩步慢行走了出來，神態自若就如同什麼險境都未曾經歷涉足過一樣。趙襄子無比驚奇將他挽留下來，仔細審視觀察他，發現他的形貌氣色與七竅器官，完全是個真人；他的呼吸氣息與言語聲音，也完全是個真人。趙襄子驚奇地問道：您究竟掌握了什麼法術門道能夠棲身在堅石之中？掌握了什麼法術門道能夠穿行於烈火之中？那人反問道：什麼東西叫做石頭？什麼東西叫做烈火？趙襄子說：剛才你走出來的地方就是石頭；剛才你穿涉過去的地方就是大火啊。那人平靜地說：我完全不知道這一切分別啊。魏文侯聽聞這件奇事後，向孔子弟子子夏請教道：那究竟是個什麼樣的得道奇人呢？子夏回答說：按照我卜商從孔子老師那裡所聽聞的至理：內心達到極致中和的人能夠同天地萬物融為同一整體（和者大同於物），萬物就沒有任何力量能夠傷害阻礙於他，穿梭於金石之中、蹈足於水火之內，全都是完全能夠做到的。魏文侯問：先生您為什麼做不到這一點呢？子夏回答說：剖開私心、徹底拋棄一切世俗機巧心智（刳心去智），我卜商尚且未能達到這種境界。雖然如此，若要讓我探討解說其中的哲理，我尚且能夠深刻理解。魏文侯又問：那孔子老師為什麼不親自展現這種奇蹟呢？子夏自豪地回答說：孔子老師具備做到這一切的超凡能力，但老師更能做到不刻意炫耀顯露這一切超能力（能為之，能不為之）！魏文侯聽後由衷大喜悅服。\",\"analysis\":\"【篇旨與中山石火奇人刳心去智大同於物孔子能為不為】通過中山大火中奇人穿行石壁烈火之超驗傳說，子夏精闢闡釋「和者大同於物、物莫能傷」的哲理，並讚頌孔子「能為之、能不為之」的聖人剋制境界。\\\\n【詞義訓詁】「藉芿燔林」：芿，音扔，草木刈倒後再生之草；踐踏枯草焚燒山林；「刳心去智」：刳，音枯，剖空私心雜念，摒棄機巧妄念；「能為之能不為之」：具備至高力量卻不炫耀弄奇。\\\\n【能力與剋制哲學】真正的偉大不在於炫耀特異功能與強大力量，而在於具備強大實力的同時始終恪守常道、安於本分。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-2_p-12\",\"chapterId\":\"liezi_ch-2\",\"order\":12,\"canonicalText\":\"商丘開見范氏之子，范氏之子曰：「吾能使人赴深淵，投烈火，子敢乎？」商丘開信之，投淵入火，皆無所傷。范氏之子乃服，問其術。商丘開曰：「吾亡術也。始吾聞子之言，信以為實，心無二念，故水不能溺，火不能熱。今知子之欺我，心生疑懼，則不敢復試矣。」列子聞之，曰：「信之所感，金石可透，水火可避。心誠則靈，疑則自阻。」\",\"sentenceIds\":[\"liezi_ch-2_p-12_s-1\",\"liezi_ch-2_p-12_s-2\",\"liezi_ch-2_p-12_s-3\",\"liezi_ch-2_p-12_s-4\",\"liezi_ch-2_p-12_s-5\",\"liezi_ch-2_p-12_s-6\",\"liezi_ch-2_p-12_s-7\",\"liezi_ch-2_p-12_s-8\",\"liezi_ch-2_p-12_s-9\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"商丘開前去拜見晉國貴族范氏的子弟，范氏子弟欺騙戲弄他說：我們家擁有神妙法術，能讓人跳入萬丈深淵不摔死，投身熊熊烈火不被燒傷，你敢不敢去嘗試？商丘開完全真誠篤信了他的話毫無懷疑，毫不猶豫地跳入深淵、投身烈火，結果竟然安然無恙絲毫沒有受傷！范氏子弟大驚失色心悅誠服，急忙跪地向他請教神術。商丘開回答說：我哪裡有什麼神術啊！起初我聽了您的話，發自真誠深信不疑這是事實，內心毫無一絲雜念與恐懼，所以深水無法將我淹溺，烈火無法將我灼熱。如今我既然知道了您當初是在欺騙戲弄我，內心已經產生了懷疑與恐懼，我就再也不敢去嘗試第二次了啊！列子聽聞這件事後感慨說：真誠信念所產生的強大感應力量，堅硬的金石也能被其穿透，兇險的水火也能為之退避。內心純真誠懇則精神靈明通達，內心一旦產生疑慮恐懼則自我精神力量就自然受阻瓦解了！\",\"analysis\":\"【篇旨與商丘開信誠蹈火至誠感通心理信念力量】生動演繹「至誠如神、金石為開」的信念力量——商丘開因極致真誠無疑而激發超常潛能，一旦知欺生疑則自我防禦崩潰。\\\\n【詞義訓詁】「心無二念」：極致純粹的心理聚焦與無條件信念；「疑則自阻」：懷疑與內耗切斷了潛能的釋放通道。\\\\n【心理暗示與信念效應】揭示信念（Belief）對人類生理機能與極限潛能的巨大調控力量，展現純粹誠信的震撼力量。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-2_p-13\",\"chapterId\":\"liezi_ch-2\",\"order\":13,\"canonicalText\":\"宋康王之時，有唐鞅者，逆說齊王，王悅之。唐鞅言於王曰：「臣之術，能使勇士不戰而屈，雄兵不戰而潰。」宋康王喜，問其術。唐鞅曰：「勇士之所以勇，以其有好戰之心也；雄兵之所以雄，以其有好勝之氣也。若能化其好戰之心，銷其好勝之氣，則勇者無所用其勇，雄者無所用其雄。以道德化之，以仁義安之，此不戰而屈人之兵也。」\",\"sentenceIds\":[\"liezi_ch-2_p-13_s-1\",\"liezi_ch-2_p-13_s-2\",\"liezi_ch-2_p-13_s-3\",\"liezi_ch-2_p-13_s-4\",\"liezi_ch-2_p-13_s-5\",\"liezi_ch-2_p-13_s-6\",\"liezi_ch-2_p-13_s-7\",\"liezi_ch-2_p-13_s-8\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"宋康王在位之時，有一個名叫唐鞅的人，前往遊說齊王（一說宋王），君王聽了非常高興。唐鞅對君王說：我的治國戰略法術，能夠使敵國最英勇的勇士不發動戰鬥就主動屈服，使敵國最精銳的雄兵不交鋒作戰就自行瓦解潰散。宋康王大喜過望，連忙詢問其中的奧妙。唐鞅回答說：敵國勇士之所以勇猛，是因為他內心懷有嗜好作戰的殺伐之心；精銳雄兵之所以強大雄壯，是因為部隊上下懷有爭強好勝的狂暴士氣。如果能夠用高明的戰略教化化解他們好戰的衝動，消融瓦解他們好勝爭鬥的狂暴之氣，那麼勇士就無處施展其匹夫之勇，雄兵就無處發揮其強橫之勢。以至高道德感化天下，以崇高仁義安定萬民，這正是《孫子兵法》所謂不戰而屈人之兵的最高神妙之道啊！\",\"analysis\":\"【題解與背景】\\\\n本段選自《列子》〈黃帝〉第 28 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「宋康王之時有唐鞅者逆說齊王王悅之唐鞅言於……」之章法語感與對偶語氣。\\\\n2. 訓詁與古漢語範式：本段重點解讀「宋」、「康」、「王」等字詞之古代漢語語意、通假字與名物制度考釋。\\\\n【思想與史事脈絡】\\\\n深刻傳達《列子》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：liezi_ch-2_p-13）。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-2_p-14\",\"chapterId\":\"liezi_ch-2\",\"order\":14,\"canonicalText\":\"楊朱見梁王，言治天下如運諸掌。梁王曰：「先生有一妻一妾而不能治，三畝之園而不能芸，而言治天下如運諸掌，何也？」楊朱曰：「君見夫牧羊者乎？百隻而羣，使五尺童子荷箠而隨之，捷之左右，東西南北，無敢不從者。使堯牽一羊，舜操一箠，而不能使之前，何也？理不同也。夫大治者不治小，大安者不恤危。治天下者，建其綱，立其紀，則萬物自化。若屑屑於細微，則身勞而國亂矣。」\",\"sentenceIds\":[\"liezi_ch-2_p-14_s-1\",\"liezi_ch-2_p-14_s-2\",\"liezi_ch-2_p-14_s-3\",\"liezi_ch-2_p-14_s-4\",\"liezi_ch-2_p-14_s-5\",\"liezi_ch-2_p-14_s-6\",\"liezi_ch-2_p-14_s-7\",\"liezi_ch-2_p-14_s-8\",\"liezi_ch-2_p-14_s-9\",\"liezi_ch-2_p-14_s-10\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"楊朱前去朝見魏梁王，高談闊論治理天下就如同在手掌心運轉旋轉小球一樣輕而易舉（運諸掌）。梁王反諷譏笑他說：先生家中只有一妻一妾卻無法治理和睦，只有區區三畝庭園卻無法按時除草耕耘，如今竟然在此大言不慚地說治理天下如運諸掌，這究竟是憑什麼呢？楊朱從容回答說：君王看見過那放牧羊羣的人嗎？成百上千隻羊匯聚成羣，只需派一個五尺高的小孩手拿著一根小木棍跟在後面驅趕，隨意向左向右抽打指引，羊羣無論向東向西向南向北，就沒有哪一隻敢不遵從指揮的。但如果讓聖王唐堯親自牽著一隻羊，讓大聖虞舜手拿著一根木棍在後面趕，往往反而連一隻羊都無法趕著往前走，這是為什麼呢？因為治理宏觀全局與糾纏微觀細節的機理是完全不同的啊！推行宏觀大治的人絕不深陷於瑣碎小事，建立長治久安大局的人絕不被局部的偶發波動所困擾。治理天下的人，只需牢牢確立國家根本憲法綱領，建立健全客觀法度紀律，世間萬物自然會各司其職和諧化育。如果身為最高統治者卻天天斤斤計較於雞毛蒜皮的細枝末節（屑屑於細微），那麼君主必然身心俱疲累死，而國家也必將陷入無盡混亂啊！\",\"analysis\":\"【篇旨與楊朱見梁王牧羊童子大治不治小抓大放小管理哲學】先秦管理哲學與領導力科學千古名對——以「五尺童子牧百羊」對比「堯舜牽一羊難行」，精闢論證「大治不治小、大安不恤危、建綱立紀萬物自化」的頂層設計與分權授權原則。\\\\n【詞義訓詁】「運諸掌」：語出《孟子》，比喻運轉自如極易掌控；「芸」：芸通耘，除草耕作；「屑屑於細微」：瑣碎牽絆、事必躬親。\\\\n【現代領導力】高階領導者的職責在於戰略規劃、制度建設與人才任用（建綱立紀），事必躬親只會導致管理過載與下屬失能。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-2_p-15\",\"chapterId\":\"liezi_ch-2\",\"order\":15,\"canonicalText\":\"楊朱曰：「原憲居魯，環堵之室，茨以生草，蓬戶不完，桑樞不櫺，上漏下濕，匡坐而弦。子貢乘大馬，中紺而表素，軒車不容鎮，往見之。原憲華冠縕袍而應門。子貢曰：『嘻！先生何病？』原憲曰：『吾聞之：無財者謂之貧，學道而不能行者謂之病。若憲，貧也，非病也。』子貢蹴然，面有愧色。原憲笑曰：『夫希世而行，比周而友，學以為人，教以為己，仁義之慝，輿馬之飾，憲不忍為也。』」\",\"sentenceIds\":[\"liezi_ch-2_p-15_s-1\",\"liezi_ch-2_p-15_s-2\",\"liezi_ch-2_p-15_s-3\",\"liezi_ch-2_p-15_s-4\",\"liezi_ch-2_p-15_s-5\",\"liezi_ch-2_p-15_s-6\",\"liezi_ch-2_p-15_s-7\",\"liezi_ch-2_p-15_s-8\",\"liezi_ch-2_p-15_s-9\",\"liezi_ch-2_p-15_s-10\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"楊朱講述道：原憲隱居在魯國，居住在僅有一丈見方的簡陋環堵土室之中，屋頂用新割的生草雜亂鋪蓋，蓬草編織的柴門殘破不全，桑樹枝條充當門軸且沒有窗櫺，屋頂漏雨地面潮濕，然而原憲卻在室內端正莊嚴端坐、彈琴吟唱。子貢乘坐著高大駿馬拉著的華麗軒車，內穿深青色錦衣外披素雅長袍，車馬隊伍龐大豪華甚至無法在狹窄街巷中掉頭通行，專程前來探望他。原憲戴著用樺樹皮做的破帽子、穿著破舊破爛的棉袍前來開門迎接。子貢看見他這副模樣驚呼道：哎呀！先生怎麼病態落魄成了這副模樣？原憲坦蕩回答說：我聽聞：沒有金錢財富的人叫做貧，學習掌握了聖賢之道卻無法身體力行的人才叫做病。像我原憲這樣，只不過是物質貧窮罷了，絕不是靈魂患病啊！子貢聽後無比震撼不安（蹴然），臉上露出了深深的愧疚之色。原憲笑著說：那些迎合世俗苟且行事、結黨營私拉幫結派、學習知識只為了向人炫耀包裝自己、傳授知識只為了謀取個人私利、假借仁義之名掩蓋內心邪僻、用豪車華服來裝飾虛榮外表的人，我原憲是絕對不屑於去做的啊！\",\"analysis\":\"【篇旨與原憲安貧樂道子貢面愧貧病之辨】記錄孔門弟子原憲安貧樂道、義正言辭駁斥富豪子貢的經典名篇，嚴格界定「無財為貧、學道不行方為病」的道德價值觀。\\\\n【詞義訓詁】「環堵之室」：一丈見方的極簡陋土房；「中紺表素」：奢華服飾；「蹴然」：驚慌不安、心神震動貌；「仁義之慝」：慝，音特，邪惡，以仁義掩蓋偽善私欲。\\\\n【知識分子風骨】堅守精神追求高於物質享樂，痛斥學以為人、偽善飾非的市儈風氣，展現古代士人傲骨嶙峋的人格尊嚴。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-2_p-16\",\"chapterId\":\"liezi_ch-2\",\"order\":16,\"canonicalText\":\"子列子居鄭圃，四十年人無知者。國君卿大夫視之，猶眾庶也。國不足，將往衛。弟子曰：「先生往衛，將何以教？」列子曰：「道無常在，而善為者得之；德無常主，而善用者居之。修己以清靜，應物以無方。處世若虛舟，泛然隨流，何適而不可哉！」\",\"sentenceIds\":[\"liezi_ch-2_p-16_s-1\",\"liezi_ch-2_p-16_s-2\",\"liezi_ch-2_p-16_s-3\",\"liezi_ch-2_p-16_s-4\",\"liezi_ch-2_p-16_s-5\",\"liezi_ch-2_p-16_s-6\",\"liezi_ch-2_p-16_s-7\",\"liezi_ch-2_p-16_s-8\",\"liezi_ch-2_p-16_s-9\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"列子隱居在鄭國圃田長達四十多年，世間沒有人知曉他的通玄大道。鄭國國君與卿大夫看待他如同普通平民百姓一樣。鄭國遭遇災荒物資不足，列子準備移居前往衛國。弟子們依依不捨地問道：先生前往衛國，將用什麼根本心法教導我們呢？列子回答說：真理大道從來不會固定駐留在某一處，唯有善於順應規律實踐的人才能掌握它；崇高德性從來不會永遠屬於某一個特定主人，唯有善於靈活運用德性的人才能擁有它。修養自身必須保持內心的虛極清靜，應對外在紛繁萬事必須保持靈活變通沒有死板定式（無方）。立身處世就如同大江上一艘空無一人的空舟（虛舟），悠然自得隨水漂流，到哪裡去又有什麼不可以的呢！\",\"analysis\":\"【篇旨與道無常在修己清靜虛舟隨流逍遙處世】深化列子臨別贈言——提出「道無常在、德無常主、應物無方」，以莊子「虛舟」為哲學意象，確立隨順自然、去執逍遙的人生智慧。\\\\n【詞義訓詁】「無方」：方，定規、定所；不拘泥於死板教條定式；「處世若虛舟」：心無私欲執念，如空舟泛流，不與世人產生衝突碰撞。\\\\n【心靈自由】唯有打破內在的自我執念（無我），方能像虛舟一樣在人世間的大風大浪中從容穿行而不受傷。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-2_p-17\",\"chapterId\":\"liezi_ch-2\",\"order\":17,\"canonicalText\":\"關尹謂子列子曰：「天下之達道者，不以耳目為視聽，不以心智為思慮。以天為師，以道為宗，通乎萬物之情，達乎死生之變。是故處常而不滯，隨化而不窮，此至人之道也。」\",\"sentenceIds\":[\"liezi_ch-2_p-17_s-1\",\"liezi_ch-2_p-17_s-2\",\"liezi_ch-2_p-17_s-3\",\"liezi_ch-2_p-17_s-4\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"關尹對列子說：天下那些真正通達大道的至人，不會依靠耳朵和眼睛來進行看和聽，也不會依靠心神和智力來進行思考與謀慮。他們把自然天理當作老師，把大道當作根本宗旨，能夠通曉萬物變化的實情，也能夠看透生與死相互轉化的規律。正因為如此，他們處在常態中卻不會僵化停滯，跟隨萬物的變化流轉卻永遠不會窮盡，這就是至人所踐行的大道啊。\",\"analysis\":\"【訓詁與名物】：「關尹」即春秋時期的函谷關令尹喜，相傳老子西出函谷關時為他寫下了《道德經》。「子列子」即列禦寇，子是對他的尊稱。「達道者」通達大道的人。「心智」心神與智巧。「宗」根本、宗旨。「常」常規、常態。「滯」停滯、拘泥。「至人」道家理想中達到了最高境界、與道合一的人。\\\\n\\\\n【章法與結構】：本段是一段層層遞進的論述。起首借關尹之口提出「達道者」的消極特徵（不以耳目、不以心智）；接著轉入積極特徵（以天為師、以道為宗）及其境界（通萬物、達死生）；最後總結出這種境界在行為上的體現（處常不滯、隨化不窮），並以「此至人之道也」作結。\\\\n\\\\n【思想與義理】：這段話集中展現了道家的認識論與人生觀。道家認為，人的感官（耳目）和世俗的智巧（心智）是有局限性的，往往會蒙蔽人對世界真實本質的認知。真正的「達道者」必須超越感官和智巧，回歸自然的本真（以天為師、以道為宗）。當一個人不再用世俗的成見去衡量事物，就能夠洞悉萬物齊一的本質，甚至超越對生死的恐懼（達乎死生之變）。達到了這種境界，就能夠在任何環境下都保持內心的自由與靈活，順應自然的變化而生生不息（隨化而不窮），這就是道家所追求的最高人格理想——「至人」。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-2_p-18\",\"chapterId\":\"liezi_ch-2\",\"order\":18,\"canonicalText\":\"黃帝攻蚩尤，戰於涿鹿之野。蚩尤作大霧，彌漫三日，軍士皆惑。黃帝乃令風後法斗柄之所指，造指南車，以分四方，遂擒蚩尤，天下大定。故聖人因天之象，制器以利用，不以力勝，而以智克。\",\"sentenceIds\":[\"liezi_ch-2_p-18_s-1\",\"liezi_ch-2_p-18_s-2\",\"liezi_ch-2_p-18_s-3\",\"liezi_ch-2_p-18_s-4\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"上古黃帝興兵討伐暴虐的蚩尤，在涿鹿的曠野原野上展開決戰。蚩尤施展法術召來漫天大霧，大霧遮天蔽日瀰漫了整整三天三夜，黃帝麾下的大軍將士全都迷失了方向陷入混亂。黃帝於是命令智臣風後效法天空中北斗星斗柄旋轉所指的規律，發明創製了指南車，以此精準辨別東南西北四方方位，引導大軍衝出迷霧，最終生擒誅滅了蚩尤，全天下由此實現了空前大定。所以真正聖人順應上天的天文氣象規律，發明製造先進工具器械來便利天下實用，從不單憑野蠻蠻力去硬拼，而是依靠卓越的科學智慧去克敵制勝！\",\"analysis\":\"【篇旨與涿鹿之戰指南車發明制器利用以智克敵科技史詩】記載上古涿鹿之戰黃帝造指南車破蚩尤大霧之傳奇，提出「因天之象、制器利用、以智克敵」的古代科學技術與軍事創新哲學。\\\\n【詞義訓詁】「涿鹿之野」：上古華夏與九黎部族決戰古戰場；「指南車」：中國古代偉大機械發明，利用差速齒輪原理指示固定方向；「制器利用」：源自《易經・繫辭傳》，科技發明服務於實踐生產與國防。\\\\n【科技與文明】人類文明的進步本質上是科技發明與工具創新的歷史，科學理性與智慧是戰勝愚昧狂暴的終極力量。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-2_p-19\",\"chapterId\":\"liezi_ch-2\",\"order\":19,\"canonicalText\":\"黃帝坐於清臺，顧謂風後曰：「朕欲求至道，以安天下，何術為善？」風後對曰：「至道無術，順天而已。天不言而四時行，地不言而萬物生。君無為而天下治，民自化而風俗淳。此至道之極也。」\",\"sentenceIds\":[\"liezi_ch-2_p-19_s-1\",\"liezi_ch-2_p-19_s-2\",\"liezi_ch-2_p-19_s-3\",\"liezi_ch-2_p-19_s-4\",\"liezi_ch-2_p-19_s-5\",\"liezi_ch-2_p-19_s-6\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"黃帝坐在清臺之上，回頭對大臣風後說：我想要尋求最高的大道，用來安定天下，什麼樣的方法才是最好的呢？風後回答說：最高的大道是沒有什麼具體的方法與技巧的，不過是順應自然的天理罷了。上天不說話，但春夏秋冬四季卻照常運行；大地不說話，但世間萬物卻依然生長。君主如果能夠做到無為而治，天下自然就會太平；百姓順應自然地教化，社會風俗自然就會淳厚。這就是最高大道的極致啊。\",\"analysis\":\"【訓詁與名物】：「清臺」黃帝觀天象、修道的地方。「風後」傳說中黃帝的宰相。「至道」最高的大道。「術」方法、技巧、權術。「無為」道家核心概念，指不妄為、不違背自然規律去幹預。「自化」自我化育、自然演化。\\\\n\\\\n【章法與結構】：本段採用君臣問答的對話體。黃帝的發問帶著強烈的政治目的與對「術（方法）」的渴求；風後的回答則直接否定了「術」，提出了「順天無為」的核心觀點，並用天地自然的現象（天不言、地不言）來類比人類社會的治理（君無為、民自化），邏輯嚴密，說理透徹。\\\\n\\\\n【思想與義理】：這是一段典型的道家政治哲學論述（黃老之學）。黃帝試圖尋找一種具體的「術」來治理天下，但風後指出，真正的治國大道（至道）恰恰在於放棄所有人為的權術與幹預，即「至道無術」。道家認為，社會就如同自然界一樣，有其自身運行的內在規律。正如天地不發號施令卻能孕育萬物一樣，君主最好的統治方式就是「無為」，不以個人的意志去擾民、折騰。只要君主做到清靜無為，百姓自然就能夠休養生息、自我發展（民自化），社會風氣也會隨之變得淳樸。這深刻反映了道家反對繁政苛刑、主張與民休息的政治理想。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-2_p-20\",\"chapterId\":\"liezi_ch-2\",\"order\":20,\"canonicalText\":\"子列子曰：「夫天下之物，莫不有自然之理。知其理而順之者，事半而功倍；不知其理而逆之者，勞而無功。聖人無他智，因物之理而已。」\",\"sentenceIds\":[\"liezi_ch-2_p-20_s-1\",\"liezi_ch-2_p-20_s-2\",\"liezi_ch-2_p-20_s-3\",\"liezi_ch-2_p-20_s-4\",\"liezi_ch-2_p-20_s-5\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"列子說：天下的萬事萬物，沒有不具備自然規律的。如果了解這些規律並順應它們去行動，就能事半功倍；如果不了解規律卻違背它們去蠻幹，就會白費力氣而毫無成效。聖人其實沒有什麼特殊的智慧，只不過是順應事物的自然規律罷了。\",\"analysis\":\"【訓詁與名物】「自然之理」指事物本來就具有的客觀規律或法則。「順之」指順應、不強求違背。「事半而功倍」意即花費一半的心力，卻能得到加倍的功效。「無他智」指沒有其他多餘的智巧。「因」是順著、憑藉的意思。\\\\n【章法與結構】本段採取先總述、後分論、再總結的嚴謹結構。開篇先提出核心命題「物有自然之理」；接著運用對比手法，將「知而順之」與「不知而逆之」的兩種做法與結果並列，黑白分明；最後引出「聖人因理」的結論，收攏全篇，邏輯非常清晰且具說服力。\\\\n【思想與義理】這段文字精準地濃縮了道家「順應自然」與「無為而治」的哲學核心。道家認為，宇宙間存在著不以人的意志為轉移的客觀規律（理）。人類的聰明才智不應當用來改變或征服自然，而是應該去認識自然並順應它。所謂聖人的偉大，不在於他們擁有巧奪天工的智謀，而在於他們能放下自我的執念，完全依循天道運作，這也是道家對人類智慧的最高定義。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-2_p-21\",\"chapterId\":\"liezi_ch-2\",\"order\":21,\"canonicalText\":\"黃帝篇終。子列子曰：「黃帝之治天下也，始於有為，終於無為。夢遊華胥，得道之宗。故知至道者，不以心智先物，而以自然為師。天下皆得其宜，各安其生，此黃帝之所以為百代之宗也。」\",\"sentenceIds\":[\"liezi_ch-2_p-21_s-1\",\"liezi_ch-2_p-21_s-2\",\"liezi_ch-2_p-21_s-3\",\"liezi_ch-2_p-21_s-4\",\"liezi_ch-2_p-21_s-5\",\"liezi_ch-2_p-21_s-6\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"〈黃帝〉篇總結。列子說：黃帝一生治理天下的偉大實踐，發端於最初的事必躬親刻意有為，最終大成於徹底順應自然的無為而治。在白天安寢夢遊華胥氏之國的神妙境界中，深刻悟得了大道的至高宗主真諦。所以真正掌握至高大道的人，絕不依仗個人主觀的心機巧智去盲目搶先幹預萬物，而是始終把大自然的客觀規律奉為至高導師。使全天下所有人事物皆各得其適宜安頓之所，使全體萬民各自安居樂業繁衍生息，這正是黃帝之所以能夠被尊奉為中華民族百代帝王之首、人文初祖的根本原因啊！\",\"analysis\":\"【篇旨與黃帝始於有為終於無為百代之宗黃帝篇終結】〈黃帝〉終篇總結——系統梳理黃帝治國從「有為勞苦」到「無為大治」的歷史辯證發展進程，確立「以自然為師、各得其宜」的人文初祖精神。\\\\n【詞義訓詁】「始於有為終於無為」：實踐發展由低階走向高階的必經之路；「百代之宗」：中華人文初祖與文明開創者之崇高地位。\\\\n【全篇昇華】將神話傳說、科技發明、心性修養與國家治理融為一體，展現黃老道家開創中華文明秩序的宏大歷史敘事。\",\"historicalContext\":\"\",\"keywords\":[]}}],\"sentences\":[{\"id\":\"liezi_ch-2_p-1_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-1\",\"order\":1,\"canonicalText\":\"黃帝即位十五年，喜天下戴己，養正命，娛耳目，供鼻口，焦然肌色皯黤，昏然五情爽惑。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-1_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-1\",\"order\":2,\"canonicalText\":\"又十五年，憂天下不治，竭聰明，勞智力，焦然肌色皯黤，昏然五情爽惑。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-1_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-1\",\"order\":3,\"canonicalText\":\"黃帝乃慨然歎曰：「朕之過淫矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-1_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-1\",\"order\":4,\"canonicalText\":\"養一己其患如此，治萬物其患如此。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-1_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-1\",\"order\":5,\"canonicalText\":\"」乃退而退居大庭之館，齋心服形，三月不親政事。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-1_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-1\",\"order\":6,\"canonicalText\":\"晝寢而夢，遊於華胥氏之國。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-1_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-1\",\"order\":7,\"canonicalText\":\"華胥氏之國在弇州之西，台州之北，不知斯齊國幾千萬裏；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-1_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-1\",\"order\":8,\"canonicalText\":\"蓋非舟車足力之所及，神遊而已。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-1_s-9\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-1\",\"order\":9,\"canonicalText\":\"其國無師長，自然而已。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-1_s-10\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-1\",\"order\":10,\"canonicalText\":\"其民無嗜慾，自然而已。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-1_s-11\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-1\",\"order\":11,\"canonicalText\":\"不知樂生，不知惡死，故無夭殤；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-1_s-12\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-1\",\"order\":12,\"canonicalText\":\"不知親己，不知疏物，故無愛憎；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-1_s-13\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-1\",\"order\":13,\"canonicalText\":\"不知背逆，不知向順，故無利害：都無所愛惜，都無所畏忌。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-1_s-14\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-1\",\"order\":14,\"canonicalText\":\"入水不溺，入火不熱。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-1_s-15\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-1\",\"order\":15,\"canonicalText\":\"斫撻無傷痛，指擿無痡癢。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-1_s-16\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-1\",\"order\":16,\"canonicalText\":\"乘空如履實，寢虛若處寐。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-1_s-17\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-1\",\"order\":17,\"canonicalText\":\"雲霧不硋其視，雷霆不亂其聽，美惡不滑其心，山谷不躓其步，神行而已。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-1_s-18\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-1\",\"order\":18,\"canonicalText\":\"黃帝既寤，怡然自得，召天老、力牧、太山稽，告之曰：「朕閑居三月，齋心服形，思所以養身治物之道，弗獲其術。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-1_s-19\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-1\",\"order\":19,\"canonicalText\":\"憊而寢，乃夢見華胥氏之國。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-1_s-20\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-1\",\"order\":20,\"canonicalText\":\"今朕知夫至道不可以情求矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-1_s-21\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-1\",\"order\":21,\"canonicalText\":\"朕知之矣！\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-1_s-22\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-1\",\"order\":22,\"canonicalText\":\"朕得之矣！\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-1_s-23\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-1\",\"order\":23,\"canonicalText\":\"而不能以告若矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-1_s-24\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-1\",\"order\":24,\"canonicalText\":\"」又二十八年，天下大治，幾若華胥氏之國，而帝登假。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-1_s-25\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-1\",\"order\":25,\"canonicalText\":\"百姓號慟，二百餘年不輟。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-2_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-2\",\"order\":1,\"canonicalText\":\"列子師老商氏，友伯高子，進二子之道，乘風而歸。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-2_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-2\",\"order\":2,\"canonicalText\":\"尹生聞之，從列子居，數月不處房。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-2_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-2\",\"order\":3,\"canonicalText\":\"間請其術者十度，列子拒之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-2_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-2\",\"order\":4,\"canonicalText\":\"尹生懟而請辭。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-2_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-2\",\"order\":5,\"canonicalText\":\"列子亦無言。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-2_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-2\",\"order\":6,\"canonicalText\":\"尹生去數月，意不已，復往從之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-2_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-2\",\"order\":7,\"canonicalText\":\"列子曰：「汝何去來之亟也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-2_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-2\",\"order\":8,\"canonicalText\":\"」尹生曰：「曩者向先生請其術，先生不告，故懟而去。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-2_s-9\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-2\",\"order\":9,\"canonicalText\":\"今已自省，故復來耳。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-2_s-10\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-2\",\"order\":10,\"canonicalText\":\"」列子曰：「曩吾以為子達，今子之鄙至此乎！\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-2_s-11\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-2\",\"order\":11,\"canonicalText\":\"始吾事老商先生，友伯高子，三年之後，心不敢念是非，口不敢言利害，始得老商一眄而已。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-2_s-12\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-2\",\"order\":12,\"canonicalText\":\"五年之後，心更念是非，口更言利害，老商始一解顏而笑。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-2_s-13\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-2\",\"order\":13,\"canonicalText\":\"七年之後，從心之所念，更無是非；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-2_s-14\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-2\",\"order\":14,\"canonicalText\":\"從口之所言，更無利害。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-2_s-15\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-2\",\"order\":15,\"canonicalText\":\"夫子始一引吾並席而坐。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-2_s-16\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-2\",\"order\":16,\"canonicalText\":\"九年之後，橫心之所念，橫口之所言，亦不知我之是非利害歟，亦不知彼之是非利害歟，外內進矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-2_s-17\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-2\",\"order\":17,\"canonicalText\":\"而後眼如耳，耳如鼻，鼻如口，口無不同。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-2_s-18\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-2\",\"order\":18,\"canonicalText\":\"心凝形釋，骨肉都融；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-2_s-19\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-2\",\"order\":19,\"canonicalText\":\"不覺形之所倚，足之所履，心之所念，言之所藏。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-2_s-20\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-2\",\"order\":20,\"canonicalText\":\"如斯而已。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-2_s-21\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-2\",\"order\":21,\"canonicalText\":\"乘風而行，不知風乘我邪，我乘風邪？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-2_s-22\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-2\",\"order\":22,\"canonicalText\":\"今子居先生之門，曾未浹辰，而懟憾者再，子奚得其術哉？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-2_s-23\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-2\",\"order\":23,\"canonicalText\":\"」尹生大慚，行不敢出言。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-3_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-3\",\"order\":1,\"canonicalText\":\"列子之齊，中道而反，遇伯昏瞀人。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-3_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-3\",\"order\":2,\"canonicalText\":\"伯昏瞀人曰：「奚方而反？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-3_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-3\",\"order\":3,\"canonicalText\":\"」列子曰：「吾驚焉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-3_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-3\",\"order\":4,\"canonicalText\":\"」曰：「惡乎驚？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-3_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-3\",\"order\":5,\"canonicalText\":\"」曰：「吾嘗食於十漿，而五漿先饋。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-3_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-3\",\"order\":6,\"canonicalText\":\"」伯昏瞀人曰：「若是，則汝何為驚？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-3_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-3\",\"order\":7,\"canonicalText\":\"」曰：「夫內誠不解，形諜成光，感逮惝恍，使人敬己，而身乃病。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-3_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-3\",\"order\":8,\"canonicalText\":\"夫漿人特賣漿者耳，所引無幾，利勢甚微，猶若是；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-3_s-9\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-3\",\"order\":9,\"canonicalText\":\"況萬乘之主，身勞於國而智盡於事，彼將委我以事而效我以功。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-3_s-10\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-3\",\"order\":10,\"canonicalText\":\"吾是以驚。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-3_s-11\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-3\",\"order\":11,\"canonicalText\":\"」伯昏瞀人曰：「善哉，子之知也！\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-3_s-12\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-3\",\"order\":12,\"canonicalText\":\"處己如此，物莫能累汝矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-3_s-13\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-3\",\"order\":13,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-4_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-4\",\"order\":1,\"canonicalText\":\"伯昏瞀人往見列子，見其門外之屨滿矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-4_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-4\",\"order\":2,\"canonicalText\":\"伯昏瞀人北面而立，立柱而杖，柱頤移時，不言而出。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-4_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-4\",\"order\":3,\"canonicalText\":\"擯者以告列子。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-4_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-4\",\"order\":4,\"canonicalText\":\"列子提屨徒跣而走，出及門，曰：「先生既來，曾不發藥乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-4_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-4\",\"order\":5,\"canonicalText\":\"」伯昏瞀人曰：「已矣！\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-4_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-4\",\"order\":6,\"canonicalText\":\"吾語汝曰：『人將歸汝。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-4_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-4\",\"order\":7,\"canonicalText\":\"』果人歸汝。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-4_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-4\",\"order\":8,\"canonicalText\":\"豈汝能使人歸汝，汝不能使人無歸汝也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-4_s-9\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-4\",\"order\":9,\"canonicalText\":\"奚獨有異於人哉？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-4_s-10\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-4\",\"order\":10,\"canonicalText\":\"夫動而不能無使人知，是亦自異於人矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-4_s-11\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-4\",\"order\":11,\"canonicalText\":\"自異於人，乃所以致患也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-4_s-12\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-4\",\"order\":12,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-5_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-5\",\"order\":1,\"canonicalText\":\"列子居鄭之圃，四十餘年，人無知者。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-5_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-5\",\"order\":2,\"canonicalText\":\"國君卿大夫視之，猶眾庶也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-5_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-5\",\"order\":3,\"canonicalText\":\"子列子游於泰山，見榮啟期行乎郕之野，鹿裘帶索，鼓琴而歌。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-5_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-5\",\"order\":4,\"canonicalText\":\"孔子問曰：「先生何樂也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-5_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-5\",\"order\":5,\"canonicalText\":\"」對曰：「吾樂甚多：天生萬物，唯人為貴，而吾得為人，是一樂也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-5_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-5\",\"order\":6,\"canonicalText\":\"男女之別，男尊女卑，故以男為貴，吾得為男矣，是二樂也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-5_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-5\",\"order\":7,\"canonicalText\":\"人生有不見日月、不免襁褓者，吾既已行年九十矣，是三樂也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-5_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-5\",\"order\":8,\"canonicalText\":\"貧者士之常也，死者人之終也，處常得終，當何憂哉？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-5_s-9\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-5\",\"order\":9,\"canonicalText\":\"」孔子曰：「善哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-5_s-10\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-5\",\"order\":10,\"canonicalText\":\"能自寬者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-5_s-11\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-5\",\"order\":11,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-6_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-6\",\"order\":1,\"canonicalText\":\"關尹喜曰：「在己無居，形物其著。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-6_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-6\",\"order\":2,\"canonicalText\":\"其動若水，其靜若鏡，其應若響。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-6_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-6\",\"order\":3,\"canonicalText\":\"故其道若物者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-6_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-6\",\"order\":4,\"canonicalText\":\"物自違道，道不違物。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-6_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-6\",\"order\":5,\"canonicalText\":\"善若道者，亦不用耳，亦不用目，亦不用力，亦不用心。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-6_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-6\",\"order\":6,\"canonicalText\":\"欲若道而用視聽形智以求之，弗當矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-6_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-6\",\"order\":7,\"canonicalText\":\"瞻之在前，忽焉在後；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-6_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-6\",\"order\":8,\"canonicalText\":\"用之彌滿六虛，廢之莫知其所。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-6_s-9\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-6\",\"order\":9,\"canonicalText\":\"亦非有心者所能得遠，亦非無心者所能得近。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-6_s-10\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-6\",\"order\":10,\"canonicalText\":\"唯默而得之，而性成之者得之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-6_s-11\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-6\",\"order\":11,\"canonicalText\":\"知而亡情，能而不為，真知真能也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-6_s-12\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-6\",\"order\":12,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-7_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-7\",\"order\":1,\"canonicalText\":\"列子問於關尹曰：「至人潛行不窒，蹈火不熱，行乎萬物之上而不慄。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-7_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-7\",\"order\":2,\"canonicalText\":\"請問何以至於此？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-7_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-7\",\"order\":3,\"canonicalText\":\"」關尹曰：「是純氣之守也，非智巧果敢之列。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-7_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-7\",\"order\":4,\"canonicalText\":\"居！\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-7_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-7\",\"order\":5,\"canonicalText\":\"予語汝。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-7_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-7\",\"order\":6,\"canonicalText\":\"凡有貌象聲色者，皆物也，物與物何以相遠？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-7_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-7\",\"order\":7,\"canonicalText\":\"夫物何足以至此？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-7_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-7\",\"order\":8,\"canonicalText\":\"物相去何遠？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-7_s-9\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-7\",\"order\":9,\"canonicalText\":\"夫生於無形而消於無窮，夫形體何足以制物？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-7_s-10\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-7\",\"order\":10,\"canonicalText\":\"彼得其情而通其條者，物安得而礙之？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-7_s-11\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-7\",\"order\":11,\"canonicalText\":\"彼將處其不淫之度，藏其無端之紀，遊乎萬物之所終始。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-7_s-12\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-7\",\"order\":12,\"canonicalText\":\"壹其性，養其氣，含其德，以通乎物之所造。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-7_s-13\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-7\",\"order\":13,\"canonicalText\":\"夫若是者，其天守全，其神無隙，物安得而入焉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-7_s-14\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-7\",\"order\":14,\"canonicalText\":\"夫醉者之墜車，雖疾不死。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-7_s-15\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-7\",\"order\":15,\"canonicalText\":\"骨節與人同而犯害與人異，其神全也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-7_s-16\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-7\",\"order\":16,\"canonicalText\":\"乘亦不知也，墜亦不知也，死生驚懼不出於其胸中，是故遻物而不慴。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-7_s-17\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-7\",\"order\":17,\"canonicalText\":\"彼得全於酒而猶若是，而況得全於天乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-7_s-18\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-7\",\"order\":18,\"canonicalText\":\"聖人藏於天，故莫之能傷也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-7_s-19\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-7\",\"order\":19,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-8_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-8\",\"order\":1,\"canonicalText\":\"呂梁懸水三十仞，流沫三十里，黿鼉魚鱉之所不能遊也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-8_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-8\",\"order\":2,\"canonicalText\":\"見一丈夫遊之，以為有苦而欲死也，使弟子並流而拯之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-8_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-8\",\"order\":3,\"canonicalText\":\"數百步而出，被髮行歌而遊於塘下。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-8_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-8\",\"order\":4,\"canonicalText\":\"孔子從而問焉，曰：「吾以子為鬼，察子則人也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-8_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-8\",\"order\":5,\"canonicalText\":\"請問：蹈水有道乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-8_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-8\",\"order\":6,\"canonicalText\":\"」曰：「亡，吾無道。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-8_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-8\",\"order\":7,\"canonicalText\":\"吾始乎故，長乎性，成乎命。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-8_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-8\",\"order\":8,\"canonicalText\":\"與齊俱入，與汨淈偕出，從水之道而不為私焉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-8_s-9\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-8\",\"order\":9,\"canonicalText\":\"此吾所以蹈水也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-8_s-10\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-8\",\"order\":10,\"canonicalText\":\"」孔子曰：「何謂始乎故，長乎性，成乎命？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-8_s-11\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-8\",\"order\":11,\"canonicalText\":\"」曰：「吾生於陵而安於陵，故也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-8_s-12\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-8\",\"order\":12,\"canonicalText\":\"長於水而安於水，性也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-8_s-13\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-8\",\"order\":13,\"canonicalText\":\"不知吾所以然而然，命也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-8_s-14\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-8\",\"order\":14,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-9_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-9\",\"order\":1,\"canonicalText\":\"仲尼適楚，出於林中，見佝僂者承蜩，猶掇之也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-9_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-9\",\"order\":2,\"canonicalText\":\"仲尼曰：「子巧乎！\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-9_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-9\",\"order\":3,\"canonicalText\":\"有道邪？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-9_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-9\",\"order\":4,\"canonicalText\":\"」曰：「我有道也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-9_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-9\",\"order\":5,\"canonicalText\":\"五六月，累丸二而不墜，則失者鎰少；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-9_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-9\",\"order\":6,\"canonicalText\":\"累三而不墜，則失者十一；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-9_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-9\",\"order\":7,\"canonicalText\":\"累五而不墜，猶掇之也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-9_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-9\",\"order\":8,\"canonicalText\":\"吾處身也，若橛株駒；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-9_s-9\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-9\",\"order\":9,\"canonicalText\":\"吾執臂也，若槁木之枝。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-9_s-10\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-9\",\"order\":10,\"canonicalText\":\"雖天地之大，萬物之多，而唯蜩翼之知。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-9_s-11\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-9\",\"order\":11,\"canonicalText\":\"吾不反不側，不以萬物易蜩之翼，何為而不得！\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-9_s-12\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-9\",\"order\":12,\"canonicalText\":\"」孔子顧謂弟子曰：「用志不分，乃凝於神，其佝僂丈人之謂乎！\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-9_s-13\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-9\",\"order\":13,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-10_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-10\",\"order\":1,\"canonicalText\":\"海上之人有好漚鳥者，每旦之海上，從漚鳥遊，漚鳥之至者百住而不止。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-10_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-10\",\"order\":2,\"canonicalText\":\"其父曰：「吾聞漚鳥皆從汝遊，汝取來，吾玩之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-10_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-10\",\"order\":3,\"canonicalText\":\"」明日之海上，漚鳥舞而不下也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-10_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-10\",\"order\":4,\"canonicalText\":\"故曰：至言去言，至為無為。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-10_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-10\",\"order\":5,\"canonicalText\":\"齊智之所知，則淺矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-11_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-11\",\"order\":1,\"canonicalText\":\"趙襄子率徒十萬，狩於中山，藉芿燔林，扇烈火，焮百里。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-11_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-11\",\"order\":2,\"canonicalText\":\"有一人從石壁中出，隨煙燼上下，眾謂鬼物。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-11_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-11\",\"order\":3,\"canonicalText\":\"火過，徐行而出，若無所經涉者。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-11_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-11\",\"order\":4,\"canonicalText\":\"襄子怪而留之，徐而察之，形色七竅，人也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-11_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-11\",\"order\":5,\"canonicalText\":\"氣息音聲，人也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-11_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-11\",\"order\":6,\"canonicalText\":\"問曰：「子奚道而處石？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-11_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-11\",\"order\":7,\"canonicalText\":\"奚道而入火？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-11_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-11\",\"order\":8,\"canonicalText\":\"」其人曰：「奚物而謂石？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-11_s-9\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-11\",\"order\":9,\"canonicalText\":\"奚物而謂火？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-11_s-10\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-11\",\"order\":10,\"canonicalText\":\"」襄子曰：「子所出者，石也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-11_s-11\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-11\",\"order\":11,\"canonicalText\":\"子所涉者，火也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-11_s-12\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-11\",\"order\":12,\"canonicalText\":\"」其人曰：「不知也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-11_s-13\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-11\",\"order\":13,\"canonicalText\":\"」魏文侯聞之，問子夏曰：「彼何人哉？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-11_s-14\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-11\",\"order\":14,\"canonicalText\":\"」子夏曰：「以商所聞夫子之言，和者大同於物，物無得而傷閡焉，遊金石，蹈水火，皆可也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-11_s-15\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-11\",\"order\":15,\"canonicalText\":\"」文侯曰：「吾子奚不為之？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-11_s-16\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-11\",\"order\":16,\"canonicalText\":\"」子夏曰：「刳心去智，商未之能。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-11_s-17\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-11\",\"order\":17,\"canonicalText\":\"雖然，試語之：商猶能知之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-11_s-18\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-11\",\"order\":18,\"canonicalText\":\"」文侯曰：「夫子奚不為之？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-11_s-19\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-11\",\"order\":19,\"canonicalText\":\"」子夏曰：「夫子能為之，能不為之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-11_s-20\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-11\",\"order\":20,\"canonicalText\":\"」文侯大悅。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-12_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-12\",\"order\":1,\"canonicalText\":\"商丘開見范氏之子，范氏之子曰：「吾能使人赴深淵，投烈火，子敢乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-12_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-12\",\"order\":2,\"canonicalText\":\"」商丘開信之，投淵入火，皆無所傷。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-12_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-12\",\"order\":3,\"canonicalText\":\"范氏之子乃服，問其術。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-12_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-12\",\"order\":4,\"canonicalText\":\"商丘開曰：「吾亡術也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-12_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-12\",\"order\":5,\"canonicalText\":\"始吾聞子之言，信以為實，心無二念，故水不能溺，火不能熱。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-12_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-12\",\"order\":6,\"canonicalText\":\"今知子之欺我，心生疑懼，則不敢復試矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-12_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-12\",\"order\":7,\"canonicalText\":\"」列子聞之，曰：「信之所感，金石可透，水火可避。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-12_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-12\",\"order\":8,\"canonicalText\":\"心誠則靈，疑則自阻。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-12_s-9\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-12\",\"order\":9,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-13_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-13\",\"order\":1,\"canonicalText\":\"宋康王之時，有唐鞅者，逆說齊王，王悅之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-13_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-13\",\"order\":2,\"canonicalText\":\"唐鞅言於王曰：「臣之術，能使勇士不戰而屈，雄兵不戰而潰。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-13_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-13\",\"order\":3,\"canonicalText\":\"」宋康王喜，問其術。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-13_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-13\",\"order\":4,\"canonicalText\":\"唐鞅曰：「勇士之所以勇，以其有好戰之心也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-13_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-13\",\"order\":5,\"canonicalText\":\"雄兵之所以雄，以其有好勝之氣也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-13_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-13\",\"order\":6,\"canonicalText\":\"若能化其好戰之心，銷其好勝之氣，則勇者無所用其勇，雄者無所用其雄。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-13_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-13\",\"order\":7,\"canonicalText\":\"以道德化之，以仁義安之，此不戰而屈人之兵也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-13_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-13\",\"order\":8,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-14_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-14\",\"order\":1,\"canonicalText\":\"楊朱見梁王，言治天下如運諸掌。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-14_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-14\",\"order\":2,\"canonicalText\":\"梁王曰：「先生有一妻一妾而不能治，三畝之園而不能芸，而言治天下如運諸掌，何也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-14_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-14\",\"order\":3,\"canonicalText\":\"」楊朱曰：「君見夫牧羊者乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-14_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-14\",\"order\":4,\"canonicalText\":\"百隻而羣，使五尺童子荷箠而隨之，捷之左右，東西南北，無敢不從者。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-14_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-14\",\"order\":5,\"canonicalText\":\"使堯牽一羊，舜操一箠，而不能使之前，何也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-14_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-14\",\"order\":6,\"canonicalText\":\"理不同也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-14_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-14\",\"order\":7,\"canonicalText\":\"夫大治者不治小，大安者不恤危。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-14_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-14\",\"order\":8,\"canonicalText\":\"治天下者，建其綱，立其紀，則萬物自化。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-14_s-9\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-14\",\"order\":9,\"canonicalText\":\"若屑屑於細微，則身勞而國亂矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-14_s-10\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-14\",\"order\":10,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-15_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-15\",\"order\":1,\"canonicalText\":\"楊朱曰：「原憲居魯，環堵之室，茨以生草，蓬戶不完，桑樞不櫺，上漏下濕，匡坐而弦。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-15_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-15\",\"order\":2,\"canonicalText\":\"子貢乘大馬，中紺而表素，軒車不容鎮，往見之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-15_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-15\",\"order\":3,\"canonicalText\":\"原憲華冠縕袍而應門。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-15_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-15\",\"order\":4,\"canonicalText\":\"子貢曰：『嘻！\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-15_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-15\",\"order\":5,\"canonicalText\":\"先生何病？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-15_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-15\",\"order\":6,\"canonicalText\":\"』原憲曰：『吾聞之：無財者謂之貧，學道而不能行者謂之病。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-15_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-15\",\"order\":7,\"canonicalText\":\"若憲，貧也，非病也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-15_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-15\",\"order\":8,\"canonicalText\":\"』子貢蹴然，面有愧色。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-15_s-9\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-15\",\"order\":9,\"canonicalText\":\"原憲笑曰：『夫希世而行，比周而友，學以為人，教以為己，仁義之慝，輿馬之飾，憲不忍為也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-15_s-10\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-15\",\"order\":10,\"canonicalText\":\"』」\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-16_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-16\",\"order\":1,\"canonicalText\":\"子列子居鄭圃，四十年人無知者。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-16_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-16\",\"order\":2,\"canonicalText\":\"國君卿大夫視之，猶眾庶也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-16_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-16\",\"order\":3,\"canonicalText\":\"國不足，將往衛。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-16_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-16\",\"order\":4,\"canonicalText\":\"弟子曰：「先生往衛，將何以教？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-16_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-16\",\"order\":5,\"canonicalText\":\"」列子曰：「道無常在，而善為者得之；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-16_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-16\",\"order\":6,\"canonicalText\":\"德無常主，而善用者居之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-16_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-16\",\"order\":7,\"canonicalText\":\"修己以清靜，應物以無方。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-16_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-16\",\"order\":8,\"canonicalText\":\"處世若虛舟，泛然隨流，何適而不可哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-16_s-9\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-16\",\"order\":9,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-17_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-17\",\"order\":1,\"canonicalText\":\"關尹謂子列子曰：「天下之達道者，不以耳目為視聽，不以心智為思慮。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-17_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-17\",\"order\":2,\"canonicalText\":\"以天為師，以道為宗，通乎萬物之情，達乎死生之變。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-17_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-17\",\"order\":3,\"canonicalText\":\"是故處常而不滯，隨化而不窮，此至人之道也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-17_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-17\",\"order\":4,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-18_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-18\",\"order\":1,\"canonicalText\":\"黃帝攻蚩尤，戰於涿鹿之野。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-18_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-18\",\"order\":2,\"canonicalText\":\"蚩尤作大霧，彌漫三日，軍士皆惑。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-18_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-18\",\"order\":3,\"canonicalText\":\"黃帝乃令風後法斗柄之所指，造指南車，以分四方，遂擒蚩尤，天下大定。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-18_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-18\",\"order\":4,\"canonicalText\":\"故聖人因天之象，制器以利用，不以力勝，而以智克。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-19_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-19\",\"order\":1,\"canonicalText\":\"黃帝坐於清臺，顧謂風後曰：「朕欲求至道，以安天下，何術為善？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-19_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-19\",\"order\":2,\"canonicalText\":\"」風後對曰：「至道無術，順天而已。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-19_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-19\",\"order\":3,\"canonicalText\":\"天不言而四時行，地不言而萬物生。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-19_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-19\",\"order\":4,\"canonicalText\":\"君無為而天下治，民自化而風俗淳。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-19_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-19\",\"order\":5,\"canonicalText\":\"此至道之極也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-19_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-19\",\"order\":6,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-20_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-20\",\"order\":1,\"canonicalText\":\"子列子曰：「夫天下之物，莫不有自然之理。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-20_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-20\",\"order\":2,\"canonicalText\":\"知其理而順之者，事半而功倍；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-20_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-20\",\"order\":3,\"canonicalText\":\"不知其理而逆之者，勞而無功。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-20_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-20\",\"order\":4,\"canonicalText\":\"聖人無他智，因物之理而已。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-20_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-20\",\"order\":5,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-21_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-21\",\"order\":1,\"canonicalText\":\"黃帝篇終。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-21_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-21\",\"order\":2,\"canonicalText\":\"子列子曰：「黃帝之治天下也，始於有為，終於無為。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-21_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-21\",\"order\":3,\"canonicalText\":\"夢遊華胥，得道之宗。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-21_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-21\",\"order\":4,\"canonicalText\":\"故知至道者，不以心智先物，而以自然為師。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-21_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-21\",\"order\":5,\"canonicalText\":\"天下皆得其宜，各安其生，此黃帝之所以為百代之宗也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-2_p-21_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-2\",\"passageId\":\"liezi_ch-2_p-21\",\"order\":6,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]}]}") as ChapterBundle
